package com.msg.ppap.semantics.api;

import java.time.Instant;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.UUID;

/**
 * PPAP request (customer → supplier), exchange model {@code PpapRequest}.
 *
 * @param exchangeId exchange id generated by the customer, shared by both cases
 * @param caseNumber case number of the sender (customer)
 * @param customerBpnl customer BPNL
 * @param supplierBpnl supplier BPNL
 * @param customerPartNumber customer part number
 * @param supplierPartNumber supplier part number, if known to the customer
 * @param partName part name (German) as known to the customer
 * @param reason submission reason snapshot
 * @param level submission level snapshot
 * @param dueDate due date
 * @param remarks remarks
 * @param requestedAt time of sending
 * @param requestedBy requesting user
 * @param elements requested elements including definition snapshots
 * @param attachments attachment metadata (content is provided via pull, phase 5)
 */
public record RequestMessage(
        UUID exchangeId,
        String caseNumber,
        String customerBpnl,
        String supplierBpnl,
        String customerPartNumber,
        String supplierPartNumber,
        String partName,
        CodeName reason,
        CodeName level,
        LocalDate dueDate,
        String remarks,
        Instant requestedAt,
        String requestedBy,
        List<Element> elements,
        List<DocumentReference> attachments) {

    public RequestMessage {
        elements = elements == null ? List.of() : List.copyOf(elements);
        attachments = attachments == null ? List.of() : List.copyOf(attachments);
    }

    /** Catalogue entry snapshot. */
    public record CodeName(String code, String nameDe, String nameEn) {}

    /** Requested element. */
    public record Element(String code, String requirement, String note, Snapshot snapshot) {}

    /** Element definition at the time of the request. */
    public record Snapshot(String nameDe, String nameEn, String evidenceType, Map<String, Object> valueSchema) {}
}
